entries[230017] = { ["name"] = "Insigne des Meistersprengers", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nEinzigartig\n\"Wird den Bewohnern Lorenhalls für außergewöhnliche Dienste verliehen. Bei Teddo Brückensprenger oder Gigi Prügelplatz im Hotel Inkontinental könnt Ihr dafür mächtige Ausrüstung erhalten.\"" }
entries[230019] = { ["name"] = "Strolchs Boxenpfeife", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 [Beweglichkeit oder Stärke]\nBenutzen: Beschwört Boxenbot Ritzelfix für 5 Sek. zu Eurer Hilfe herbei, der Gegner für zusätzliche Bedrohung mit ranzigem Motorenöl verschmutzt. Ritzelfix stellt sicher, dass Ihr dafür den Kopf hinhaltet.\n\nRitzelfix verschwindet in einer Explosion, die gleichmäßig auf Gegner in der Nähe aufgeteilte 699165 Feuerschaden verursacht. Wenn Gegner vor Kurzem eingeölt wurden, erhöht sich der Feuerschaden um 15%. (500ms Abklingzeit) (1 Min, 30 Sek. Abklingzeit)\nBezwingt Strolch in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[230026] = { ["name"] = "Schrottfeld 9001", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 [Beweglichkeit oder Stärke]\nAnlegen: Bei unter 60% Gesundheit entsteht ein schützender Schrottvortex um Euch, der den erlittenen Schaden entweder 15 Sek. lang, oder bis 996802 Schaden verhindert wurden, um 50% verringert. Dieser Effekt kann nur alle 30 Sek. auftreten.\n\nNachdem das Schrottfeld im Kampf 20 Sek. lang nicht aktiviert wurde, überlädt es und erhöht Euer Tempo 12 Sek. lang um 2651 .\nGilt nur für Tankspezialisierungen.\nBezwingt Stix Kojenschrotter in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch' oder höher.\nVerkaufspreis:" }
entries[230027] = { ["name"] = "Kartenhaus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Kauft Euch ein, um 15 Sek. lang Eure Meisterschaft um [Quellwert] bis [Quellwert] zu erhöhen und die Karten zu Euren Gunsten zu mischen. Dadurch erhöht sich die minimale Meisterschaft für zukünftige Hände bis zu 3-mal um [Quellwert], bis Ihr den Kampf verlasst. (1 Min, 30 Sek. Abklingzeit)\nBezwingt den Einarmigen Banditen in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[230029] = { ["name"] = "Chrombustionsbombenanzug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 1.341.\nBenutzen: Legt den Bombenschutzanzug schnell an, um erlittenen Schaden 20 Sek. lang um 75% zu verringern oder bis 6290790 Schaden verhindert wurden.\n\nWenn der Bombenschutzanzug verbraucht ist, detoniert er und fügt Gegnern in der Nähe 529552 Feuerschaden zu, die gleichmäßig aufgeteilte werden. (1 Min, 30 Sek. Abklingzeit)\nBezwingt Gallywix in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\n\"Wenn die einzigen Optionen unmittelbarer Erfolg oder komplettes Versagen sind.\"\nVerkaufspreis:" }
entries[230032] = { ["name"] = "Überquellende Truhe des Bundes von K'aresh", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Vielzahl von Belohnungen für diejenigen, die sich als wahre Verbündete des Bundes von K'aresh erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
