entries[230184] = { ["name"] = "Chaosgeschmiedeter Greif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Dieses Reittier wuchs in einer Zeit großen Chaos auf. Es hat Strapazen überlebt, wie sie nur wenige kennen.\"\nWoW-Shop" }
