entries[230186] = { ["name"] = "Herr Muntermacher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 Intelligenz\nAnlegen: Eure Heilzauber und -fähigkeiten haben eine Chance Herrn Muntermacher für 6 Sek. herbeizurufen, der alle 2 Sek. einen Heilstrahl verschießt, der zwischen 5 verletzten Verbündeten hin- und herspringt und jeden um 55137 Gesundheit heilt.\n\nÜberheilung durch diesen Effekt lässt Verbündete Gegnern in der Nähe im Verlauf von 1.5 Sek. Naturschaden zufügen. Dieser Schaden wird durch weitere Überheilung erhöht.\nBezwingt Ritzelkrämer Lockenstock in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[230188] = { ["name"] = "Flaschendienst des Garbagio", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 1.341.\nBenutzen: Werdet zum Gipfel des ausgezeichneten Service des Garbagio und verteilt 10-mal im Verlauf von 4 Sek. Kaja'Cola Megaleicht an verletzte Verbündete. Diese heilt sie um 789757 Gesundheit und erhöht ihre Geschwindigkeit 5 Sek. lang um 1407 . Die Anzahl der Portionen wird durch Euer Tempo erhöht. (1 Min, 30 Sek. Abklingzeit)\nBezwingt den Einarmigen Banditen in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\n\"Enthält 0,01% Kaja'mit.\"\nVerkaufspreis:" }
entries[230189] = { ["name"] = "Megamagnet des Schrottmaestros", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 Beweglichkeit\nAnlegen: Eure schadensverursachenden Fähigkeiten haben eine hohe Chance, den Magneten aufzuladen, bis zu 30-mal.\nBenutzen: Kehrt die Polarität des Magneten um, um vergrabenen Müll gewaltsam zu recyceln, was Eurem Ziel $ 71728 * 1 Seuchenschaden pro Ladung zufügt. Verbleibende Virulenz fügt 5 Gegnern in der Nähe im Verlauf von 6 Sek. 10% des verursachten Schadens zu. (20 Sek. Abklingzeit)\nBezwingt Stix Kojenschrotter in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch' oder höher.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[230190] = { ["name"] = "Torqs großer roter Knopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 1.341.\nBenutzen: Entfesselt Euren inneren Sturm, um 15 Sek. lang Eure Stärke um 6712 zu erhöhen. Eure nächsten 3 Fähigkeiten verursachen einen Blitzschlag, der Eurem Primärziel ( 359475 * 1 ) Naturschaden zufügt. Der Schaden erhöht sich mit jedem weiteren Blitzschlag um 100%. (2 Min Abklingzeit)\nBezwingt den Kessel des Gemetzels in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[230191] = { ["name"] = "Leuchtendos Pilotenlicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 1.341.\nBenutzen: Entzündet das Pilotenlicht neu, um die Intelligenz 15 Sek. lang um 6712 zu erhöhen. Nach dem Einsatz von 3 schädlichen Zaubern entfesselt es einen Strahl, der Eurem Hauptziel ( 1997082 * 1 ) Feuerschaden und bis zu 5 Gegnern in seinem Weg ( 1997082 * 8 / 100 * 1 ) Schaden zufügt. (2 Min Abklingzeit)\nBezwingt den Kessel des Gemetzels in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[230192] = { ["name"] = "Mugs Mummkrug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, Euch in einen Rausch zu versetzen, der Euch 15 Sek. lang 668 kritischen Trefferwert gewährt. Im Rausch gewährt jeder eingesetzte Zauber 668 kritischen Trefferwert zusätzlich, aber die Dauer wird nicht erneuert. Dieser Effekt kann nur einmal alle 1 Sek. ausgelöst werden.\nBezwingt Mug'Zee in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\n\"Das Wort 'Mumm' wurde hastig darauf gekritzelt.\"\nVerkaufspreis:" }
entries[230193] = { ["name"] = "Meister Lock-und-Stock", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 1.341.\nAnlegen: Eure Zauber und Fähigkeiten haben eine hohe Chance, Euer Ziel für ' Präzisionssprengung ' zu markieren, was Meister Lock-und-Stock herbeiruft, der Eurem Ziel ( 790399 * 1 ) körperlichen Schaden zufügt. (3s Abklingzeit)\nBenutzen: Rekalibriert für ' Massenvernichtung ' . (20 Sek. Abklingzeit)\nBezwingt Ritzelkrämer Lockenstock in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[230194] = { ["name"] = "Hallradio", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine hohe Chance, einen Rummel auszulösen, der bis zu 5-mal 314 Tempo gewährt. Wenn Ihr den maximalen Rummel erreicht habt, vergrößert Ihr ihn für 15 Sek. um 100%, bevor er erneut beginnt.\nBezwingt Rik Resonanz in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\n\"Rik & Roll, Baby!\"\nVerkaufspreis:" }
