entries[230197] = { ["name"] = "Gangzwingers Ersatzschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Zwingt ein Gangzwinger-Trike in seine finalen Flammen des Ruhms. Es explodiert beim Zusammenstoß mit dem ersten Gegner in seinem Weg und verursacht ( 1 * 1584503 ) Feuerschaden, der auf alle Gegner in der Nähe aufgeteilt wird. (2 Min Abklingzeit)\nBezwingt Strolch in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\n\"Pedal bis zum Anschlag!\"\nVerkaufspreis:" }
entries[230198] = { ["name"] = "Auge von Kezan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 1.341.\nAnlegen: Eure Zauber und Fähigkeiten haben eine hohe Chance, das Auge zu ermächtigen und erhöhen Eure Hauptwert bis zu 20-mal um 243 . Nach Verlassen des Kampfes verfällt die Erhöhung aber schnell wieder. Wenn das Auge voll ermächtigt ist, fügt es Gegnern ( 64528 * 1 ) Feuerschaden zu oder heilt Verbündete um 96796 Gesundheit.\nBezwingt Gallywix in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[230199] = { ["name"] = "Zees Ganovenhotline", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.108 [Beweglichkeit oder Stärke]\nAnlegen: Eure Fähigkeiten haben eine Chance, ein Mitglied der Handlangertruppe herbeizurufen, das Euer Ziel 10 Sek. lang angreift. Wenn Ihr 'Kampfrausch' oder einen ähnlichen Effekt erhaltet, wird die ganze Crew beschworen.\nBezwingt Mug'Zee in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
