entries[230638] = { ["name"] = "Wildheitsabzeichen des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 1.086.\nBenutzen: Erhöht den Primärwert 15 Sek. lang um 5716 . (1 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[230639] = { ["name"] = "Inbrunstinsigne des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 1.086.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 4824 zu erhöhen.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[230640] = { ["name"] = "Emblem des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.161 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 1068896 . (2 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[230641] = { ["name"] = "Medaillon des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+2.161 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[230642] = { ["name"] = "Siegel der Anpassung des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+2.161 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
