entries[230721] = { ["name"] = "Geachtete Ausrüstungstruhe", ["text"] = "The War Within – Saison 2\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft ein Ausrüstungsteil des geachteten Gladiators, das für Eure Beutespezialisierung nützlich ist.\nErfordert eine PvP-Wertung von: 1.400 (beliebige Sparte)." }
entries[230722] = { ["name"] = "Truhe mit astraler Ausrüstung", ["text"] = "The War Within – Saison 3\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft ein Ausrüstungsteil des astralen Gladiators, das für Eure Beutespezialisierung nützlich ist.\nErfordert eine PvP-Wertung von: 1.400 (beliebige Sparte)." }
entries[230724] = { ["name"] = "Astrale Juweliersfassung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt einem PvP-Gegenstand von The War Within 1 [Sockel][Sockel] hinzu. Kann auf Helme, Amulette, Armschienen, Gürtel und Ringe angewendet werden.\n[\nSchmuck kann bis zu 2 Sockel haben.]\n\nMuss innerhalb von Saison 3 von The War Within verwendet werden.\nVerkaufspreis:" }
entries[230727] = { ["name"] = "Explosiver Sieg", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verströmt eine Siegesaura. (1 Stunde Abklingzeit)" }
entries[230728] = { ["name"] = "Experimenteller Flugsack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Rüstet den Flugsack aus und beschleunigt Euch nach oben in die Luft. Kann für wiederholte Sprünge, aber nur auf der Sireneninsel eingesetzt werden. (10 Sek. Abklingzeit)\n\"Verfügt über zwei Geschwindigkeiten. \"Was für eine Aussicht\" und \"Oh nein, nicht schon wieder\".\"\nVerkaufspreis:" }
entries[230729] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[230730] = { ["name"] = "Netherabgleicher", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Versucht, greifbare Ephemera mit Energie zu erfüllen und sie möglicherweise in etwas Körperlicheres zu verwandeln. (10 Sek. Abklingzeit)" }
entries[230731] = { ["name"] = "Pitz' Meisterwerkerfindung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Auf den wütenden G.O.L.E.M. werfen und hoffen, dass es irgendwie hilft!\n\"Bestimmt für etwas zu gebrauchen.\"" }
entries[230732] = { ["name"] = "Honig", ["text"] = "Questgegenstand\n\"Dieser Honig wurde in einem passenden Behälter abgefüllt. Ihr wisst schon, weil es eine klebrige Sauerei war, als Ihr ihn abgefüllt habt.\"" }
entries[230770] = { ["name"] = "Robuster Werkzeugkasten", ["text"] = "Questgegenstand\n\"Auf der Metallplakette steht \"Eigentum von Bargus\".\"" }
entries[230771] = { ["name"] = "Irdener Prototyp", ["text"] = "Questgegenstand\n\"Ein von Irdenen hergestelltes Gerät, das zum Aufdecken von Energiesignaturen in Mineralstrukturen eingesetzt wird.\"" }
entries[230772] = { ["name"] = "Verdichtete Leerenenergie", ["text"] = "Questgegenstand\n\"Leerenessenz, die sich in den Wogen der Leerenglasweiten auf K'aresh sammelt und sich zu einem verlockenden Köder verdichtet hat.\"" }
entries[230773] = { ["name"] = "Überladene Batterie", ["text"] = "Questgegenstand\nEinzigartig\n\"Nicht nur geladen, sondern überladen!\"" }
