entries[230792] = { ["name"] = "X-Plo-Dar 64k", ["text"] = "Questgegenstand\nBenutzen: Der X-Plo-Dar 64k ist darauf eingestellt, den Ursprung der Bombe herauszufinden." }
entries[230793] = { ["name"] = "Algarisches Zeichen der Belobigung", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nVerkaufspreis:" }
entries[230795] = { ["name"] = "Experimenteller Flugsack", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Rüstet den Flugsack aus und beschleunigt Euch nach oben in die Luft. Kann für wiederholte Sprünge, aber nur auf der Sireneninsel eingesetzt werden. (10 Sek. Abklingzeit)\n\"Verfügt über zwei Geschwindigkeiten. \"Was für eine Aussicht\" und \"Oh nein, nicht schon wieder\".\"" }
entries[230809] = { ["name"] = "Abgeschnittene Pflanzen von K'aresh", ["text"] = "Questgegenstand\n\"Der Duft der Flora auf K'aresh ist meist säuerlicher als der vieler Pflanzen von Azeroth.\"" }
entries[230850] = { ["name"] = "Tiefenbot 7001", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ruft einen Tiefenbot 7001, um zu einer zufälligen großzügigen Tiefe zu fahren. (1 Stunde Abklingzeit)\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 2 freigeschaltet." }
entries[230851] = { ["name"] = "Verzierte Arathischatulle", ["text"] = "Questgegenstand\nEinzigartig\n\"Mehrere Kristallsplitter aus Heilsturz liegen in der verziert geschnitzten Schatulle auf einem luxuriösen Kissen.\"" }
entries[230852] = { ["name"] = "Waffenmarke des geachteten Gladiators", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nEinzigartig (2)\n\"Beleg für Eure Fertigkeiten auf dem Schlachtfeld. Kann beim Rivalentor in Dornogal gegen Gladiatorenwaffen eingetauscht werden.\"\nVerkaufspreis:" }
entries[230853] = { ["name"] = "Aegis der Julzeit", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\n\"Gewährt zusätzlichen Schutz gegen Humbuge.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
