entries[230905] = { ["name"] = "Gesplitterter Funke des Glücks", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nBenutzen: Kombiniert 2 gesplitterte Funken des Glücks mit 0 Tapferkeitssteinen, um einen Funken des Glücks zu erschaffen.\nHandwerksmaterial\n\"Ein Fragment eines Funken des Glücks, der wiederhergestellt werden kann, wenn es mit einem anderen Stück kombiniert wird. Hauptsächlich erhalten durch wöchentliche Truhen.\"\nVerkaufspreis:" }
entries[230906] = { ["name"] = "Funke des Glücks", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Legt die Startgegenstandsstufe je nach Fertigungsqualität (632-645) fest und markiert den Gegenstand als 'Glücksgeschmiedet'.\n\"Durch dieses einzigartige Handwerksmaterial kann ein Gegenstand Wissen verleihen, das jenseits der Fähigkeiten des sterblichen Verstands ist.\"" }
entries[230907] = { ["name"] = "Honigwabe", ["text"] = "Questgegenstand\n\"Der Honig von K'aresh hat neben seiner Süße einen unerwarteten, leicht sauren Geschmack.\"" }
entries[230924] = { ["name"] = "Scheinwerferlichtmaterialisierer 1000", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Rückt ein Gruppenmitglied ins Rampenlicht! (1 Stunde Abklingzeit)" }
entries[230931] = { ["name"] = "Formel: Verzaubertes verwittertes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst von Khaz Algar (25)\n\"Lehrt Euch, wie man ein verzaubertes verwittertes Lorenhallwappen herstellt.\"\nVerkaufspreis:" }
entries[230932] = { ["name"] = "Formel: Verzaubertes runenverziertes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst von Khaz Algar (25)\n\"Lehrt Euch, wie man ein verzaubertes runenverziertes Lorenhallwappen herstellt.\"\nVerkaufspreis:" }
entries[230933] = { ["name"] = "Formel: Verzaubertes vergoldetes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst von Khaz Algar (25)\n\"Lehrt Euch, wie man ein verzaubertes vergoldetes Lorenhallwappen herstellt.\"\nVerkaufspreis:" }
entries[230935] = { ["name"] = "Verzaubertes vergoldetes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+20 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken des Glücks hergestellt werden.\n\"Ein magisches Wappen, das hergestellte Ausrüstung mit höherer Macht erfüllt. Ist bei Syenite in Dornogal erhältlich.\"\nVerkaufspreis:" }
entries[230936] = { ["name"] = "Verzaubertes runenverziertes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+10 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken des Glücks hergestellt werden.\n\"Ein magisches Wappen, das hergestellte Ausrüstung mit höherer Macht erfüllt. Ist bei Syenite in Dornogal erhältlich.\"\nVerkaufspreis:" }
entries[230937] = { ["name"] = "Verzaubertes verwittertes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+100 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein magisches Wappen, das hergestellte Ausrüstung mit höherer Macht erfüllt. Ist bei Syenite in Dornogal erhältlich.\"\nVerkaufspreis:" }
entries[230938] = { ["name"] = "Herzquellwasser", ["text"] = "Questgegenstand\n\"Wasser, das aus dem sprudelnden Herzen von K'aresh stammt.\"" }
entries[230940] = { ["name"] = "Flügel des saphirfarbenen Monarchfalters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n\"Fordert den Mond zu einem Schönheitswettbewerb heraus und gewinnt!\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
